import assert from 'node:assert/strict';
import test from 'node:test';
import { existsSync, readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join } from 'node:path';
import { controlPlaneHtml } from './login-html.js';

// The admin panel has exactly one implementation: the vanilla login shell
// generated by login-html.js and served by Nginx (nginx.conf) on every path. The
// React copy (App.jsx/main.jsx/lib/*) was removed in Phase 4 — it was
// reachable only via `vite dev`/`vite preview`, which no production path
// runs, and it duplicated these same three screens with zero feature
// delta. These tests guard the single implementation and the removal.

/** Every trimmed line of the generated page, for exact whole-line assertions. */
function scriptLines(html) {
  return new Set(html.split('\n').map((line) => line.trim()));
}

test('served HTML is the Control Plane login, not a stub', () => {
  const html = controlPlaneHtml('https://api.example.test');
  assert.match(html, /id="login-form"/);
  assert.match(html, /id="control-email"/);
  assert.match(html, /id="control-password"/);
  assert.match(html, />Sign in</);
  assert.match(html, /\/control\/v1\/auth\/login/);
  assert.match(html, /data-invexa="control-plane"/);
  assert.match(html, /<title>Invexa Control Plane<\/title>/);
  assert.equal(html.includes('Admin panel is ready'), false);
  assert.equal(html.includes('Invexa Retail Admin Panel'), false);
});

test('the login shell carries all three screens: login, company select, locked handoff', () => {
  const html = controlPlaneHtml('https://api.example.test');
  assert.match(html, /id="login-view"/);
  assert.match(html, /id="company-view"/);
  assert.match(html, /id="company-list"/);
  assert.match(html, /id="locked-view"/);
  assert.match(html, /\/control\/v1\/sessions\/select-company/);
});

test('the email field ships empty: no prefilled value, no credential-shaped placeholder', () => {
  const html = controlPlaneHtml('https://api.example.test');
  assert.equal(html.includes('superadmin@invexa.local'), false);
  const emailTag = html.match(/<input id="control-email"[^>]*>/)?.[0] ?? '';
  assert.notEqual(emailTag, '');
  assert.equal(emailTag.includes('value='), false);
  assert.equal(emailTag.includes('placeholder'), false);
});

test('the Nginx image serves the shell with no-store headers, a /health answer and SPA fallback', () => {
  const conf = readFileSync(new URL('../nginx.conf', import.meta.url), 'utf8');
  assert.match(conf, /add_header Cache-Control "no-store, no-cache, must-revalidate" always;/);
  assert.match(conf, /add_header X-Invexa-Panel "control-plane" always;/);
  assert.match(conf, /location = \/health \{[^}]*return 200 '\{"ok":true,"panel":"control-plane"\}';/s);
  assert.match(conf, /try_files \$uri \/index\.html =404;/);
});

test('the build bakes in both VITE_API_BASE and VITE_WEB_APP_URL', () => {
  const root = new URL('..', import.meta.url).pathname;
  execFileSync(process.execPath, ['scripts/build.mjs'], {
    cwd: root,
    env: { ...process.env, VITE_API_BASE: 'https://api.example.test', VITE_WEB_APP_URL: 'https://web.example.test' },
  });
  const lines = scriptLines(readFileSync(join(root, 'dist', 'index.html'), 'utf8'));
  assert.equal(lines.has('const API_BASE = "https://api.example.test";'), true);
  assert.equal(lines.has('const WEB_APP_URL = "https://web.example.test";'), true);
});

test('production defaults point at the self-hosted domain, not a retired host', () => {
  const lines = scriptLines(controlPlaneHtml());
  // Whole-line equality, so the exact configured hosts are asserted (no substring/regex URL matching).
  assert.equal(lines.has('const API_BASE = "https://invexaretail.com";'), true);
  assert.equal(lines.has('const WEB_APP_URL = "https://invexaretail.com";'), true);
});

test('locking a company hands the session off to the web app instead of rendering a dead-end panel', () => {
  const html = controlPlaneHtml('https://api.example.test', 'https://invexaretail.com');
  assert.match(html, /const WEB_APP_URL = "https:\/\/invexaretail\.com"/);
  assert.match(html, /window\.location\.href = WEB_APP_URL \+ "\/#\/control\?code=" \+ encodeURIComponent\(result\.code\)/);
  assert.match(html, /\/control\/v1\/sessions\/handoff/);
  assert.equal(html.includes('?session='), false, 'the session object never goes in the URL');
  assert.equal(html.includes('id="company-name"'), false);
  assert.equal(html.includes('id="locked-lede"'), false);
});

test('the dead React implementation stays deleted', () => {
  for (const dead of ['./App.jsx', './main.jsx', './index.css', './lib/api.js', './lib/session.js']) {
    assert.equal(existsSync(new URL(dead, import.meta.url)), false, `${dead} must not come back`);
  }
  assert.equal(existsSync(new URL('./login-html.js', import.meta.url)), true);
  assert.equal(existsSync(new URL('./worker.js', import.meta.url)), false, 'the Cloudflare Worker entry is retired; Nginx serves the panel');
});

/** Runs the page script against a minimal fake DOM: enough to watch the linked sign-in work. */
async function runPage(hash, fetchImpl) {
  const { runInNewContext } = await import('node:vm');
  const html = controlPlaneHtml('https://api.example.test', 'https://invexaretail.com');
  const script = html.slice(html.lastIndexOf('<script>') + 8, html.lastIndexOf('</script>'));
  const elements = new Map();
  const element = (id) => {
    if (!elements.has(id)) elements.set(id, { id, hidden: false, textContent: '', innerHTML: '', value: '', disabled: false, addEventListener() {} });
    return elements.get(id);
  };
  const storage = new Map();
  const location = { hash, pathname: '/', search: '', href: '' };
  const requests = [];
  const context = {
    document: { getElementById: element },
    localStorage: { getItem: (k) => storage.get(k) ?? null, setItem: (k, v) => storage.set(k, v), removeItem: (k) => storage.delete(k) },
    history: { replaceState: (_s, _t, url) => { location.hash = ''; location.replaced = url; } },
    window: { location },
    fetch: async (url, init) => { requests.push({ url, body: init.body ? JSON.parse(init.body) : undefined }); return fetchImpl(url); },
    console,
  };
  runInNewContext(script, context);
  await new Promise((resolve) => setTimeout(resolve, 20));
  return { storage, location, requests, element };
}

test('a linked sign-in code from the Windows app is cleared from the address bar and traded once for the session', async () => {
  const code = 'a'.repeat(43);
  const session = { platformToken: 'platform-token', user: { email: 'ops@example.test' }, companies: [] };
  const page = await runPage(`#link=${code}`, async () => ({ ok: true, json: async () => ({ success: true, session }) }));
  assert.equal(page.location.hash, '', 'the code does not stay in the address bar');
  assert.deepEqual(page.requests.map((r) => r.url), ['https://api.example.test/control/v1/auth/app-link/exchange']);
  assert.equal(page.requests[0].body.code, code);
  assert.deepEqual(JSON.parse(page.storage.get('invexa_control_session')), session);
  assert.equal(page.element('company-view').hidden, false, 'it opens on the company list, signed in');
  assert.equal(page.element('login-view').hidden, true);
});

test('an expired link code leaves the panel on its normal sign-in, and other fragments are ignored', async () => {
  const expired = await runPage(`#link=${'b'.repeat(43)}`, async () => ({ ok: false, status: 401, json: async () => ({ error: 'expired' }) }));
  assert.equal(expired.storage.size, 0);
  assert.equal(expired.element('login-view').hidden, false);
  assert.match(expired.element('login-error').textContent, /expired/);

  const other = await runPage('#link=<script>', async () => { throw new Error('must not call the API'); });
  assert.equal(other.requests.length, 0);
  assert.equal(other.element('login-view').hidden, false);
});
